// RuleExprLexerInit initializes any static state used to implement RuleExprLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewRuleExprLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func RuleExprLexerInit() {
	staticData := &RuleExprLexerLexerStaticData
	staticData.once.Do(ruleexprlexerLexerInit)
}

// NewRuleExprLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewRuleExprLexer(input antlr.CharStream) *RuleExprLexer {
	RuleExprLexerInit()
	l := new(RuleExprLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &RuleExprLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "RuleExprLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

